class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = []  # ordered list, tracks insertion order
        self.votes = {}  # option -> count
        self.total_votes = 0

    def add_option(self, option: str) -> None:
        if option not in self.votes:
            self.options.append(option)
            self.votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.votes:
            raise ValueError(f"Option '{option}' does not exist")
        self.votes[option] += 1
        self.total_votes += 1

    def winner(self) -> str | None:
        if self.total_votes < 3:
            return None
        best = None
        best_count = -1
        for option in self.options:  # insertion order; later wins ties
            count = self.votes[option]
            if count >= best_count:
                best = option
                best_count = count
        return best
